288	    public List<Pet> getPets() {
289	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
290	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
291	        return Collections.unmodifiableList(sortedPets);
292	    }
293	
294	    public void setPets(List<Pet> pets) {
295	        this.pets = new HashSet<>(pets);
296	    }
