303	    /**
304	     * Return the Pet with the given name, or null if none found for this Owner.
305	     *
306	     * @param name to test
307	     * @return true if pet name is already in use
308	     */
309	    public Pet getPet(String name) {
310	        return getPet(name, false);
311	    }
312	
313	    /**
314	     * Return the Pet with the given name, or null if none found for this Owner.
315	     *
316	     * @param name to test
317	     * @return true if pet name is already in use
318	     */
319	    public Pet getPet(String name, boolean ignoreNew) {
320	        name = name.toLowerCase();
321	        for (Pet pet : getPetsInternal()) {
322	            if (!ignoreNew || !pet.isNew()) {
323	                String compName = pet.getName();
324	                compName = compName.toLowerCase();
325	                if (compName.equals(name)) {
326	                    return pet;
327	                }
328	            }
329	        }
330	        return null;
331	    }
332	
333	    public Pet getPet(Integer petId) {
334	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
335	    }
336	
337	    @Override
338	    public String toString() {
339	        return new ToStringCreator(this)
340	
341	            .append("id", this.getId())
342	            .append("new", this.isNew())
343	            .append("lastName", this.getLastName())
344	            .append("firstName", this.getFirstName())
345	            .append("address", this.address)
346	            .append("city", this.city)
347	            .append("telephone", this.telephone)
348	            .append("email", this.email)
349	            .toString();
350	    }
351	}
