1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	
6	/**
7	 * Stamps the owner with its deterministic {@code householdId}.
8	 *
9	 * <p>Runs after {@link BuildOwner} in the {@code POST /api/owners} pipeline. The id is derived purely
10	 * from the owner's normalized last name and postcode (see {@link OwnerHousehold#householdId}), so
11	 * every owner that belongs to the same household computes the same value automatically — no opt-in
12	 * and no database coordination are needed. An owner with no postcode belongs to no household and
13	 * receives a {@code null} id.
14	 *
15	 * <p>The {@code sharesHousehold} request flag no longer takes part here: it only bypasses the
16	 * household duplicate block in {@link CheckOwnerHouseholdUnique}; it does not create the link.
17	 */
18	public class AssignOwnerHousehold {
19	
20	    public void service(@Val Owner owner) {
21	        owner.setHouseholdId(OwnerHousehold.householdId(owner.getLastName(), owner.getPostcode()));
22	    }
23	}
