2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	import java.util.Locale;
7	
8	/**
9	 * Single source of truth for the owner-household identity rule. A household is keyed on
10	 * {@code (lastName, postcode)}: two owners whose normalized last names match and whose postcodes are
11	 * equal belong to the same household and therefore share the same {@link #householdId}. The id is
12	 * <em>deterministic</em> — it is computed purely from those two values, so every owner that joins a
13	 * household arrives at the same id independently, without coordinating through the database.
14	 *
15	 * <p>Used by {@link AssignOwnerHousehold} to stamp the id onto a new owner, by
16	 * {@link CheckOwnerHouseholdUnique} to detect a second owner in the same household, and by
17	 * {@link OwnerIdentity} to derive the household segment of an owner's identity key — so the
18	 * definition of "same household" lives here and nowhere else.
19	 */
20	final class OwnerHousehold {
21	
22	    private OwnerHousehold() {
23	    }
24	
25	    /**
26	     * Reduces a value to its comparison form: trimmed, inner runs of whitespace collapsed to a
27	     * single space, and lower-cased. A {@code null} value yields an empty string.
28	     */
29	    static String normalize(String value) {
30	        if (value == null) {
31	            return "";
32	        }
33	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
34	    }
35	
36	    /**
37	     * Derives the stable household identifier shared by every owner in the same household. Owners
38	     * whose normalized last name and postcode match produce the same value, so the id can be computed
39	     * independently for each joining owner without coordinating through the database. The value is
40	     * the first 12 upper-case hex characters of the SHA-256 of the normalized
41	     * {@code "<lastName>|<postcode>"}.
42	     *
43	     * <p>A household requires a postcode: when the postcode is {@code null} or blank the owner
44	     * belongs to no household and this returns {@code null}.
45	     */
46	    static String householdId(String lastName, String postcode) {
47	        if (postcode == null || postcode.isBlank()) {
48	            return null;
49	        }
50	        String key = normalize(lastName) + "|" + postcode.trim();
51	        try {
52	            byte[] digest = MessageDigest.getInstance("SHA-256")
53	                    .digest(key.getBytes(StandardCharsets.UTF_8));
54	            StringBuilder sb = new StringBuilder();
55	            for (int i = 0; i < 6; i++) {
56	                sb.append(String.format("%02X", digest[i]));
57	            }
58	            return sb.toString();
59	        }
60	        catch (NoSuchAlgorithmException ex) {
61	            throw new IllegalStateException("SHA-256 not available", ex);
62	        }
63	    }
64	}
